    public sealed class DbConnection : DbConnectionBase<DbConnection, RemoteTables, Reducer>
    {
        public override RemoteTables Db { get; }
        public readonly RemoteReducers Reducers;
        public readonly RemoteProcedures Procedures;

        public DbConnection()
        {
            Db = new(this);
            Reducers = new(this);
            Procedures = new(this);
        }

        protected override IEventContext ToEventContext(Event<Reducer> Event) =>
        new EventContext(this, Event);

        protected override IReducerEventContext ToReducerEventContext(ReducerEvent<Reducer> reducerEvent) =>
        new ReducerEventContext(this, reducerEvent);

        protected override ISubscriptionEventContext MakeSubscriptionEventContext() =>
        new SubscriptionEventContext(this);

        protected override IErrorContext ToErrorContext(Exception exception) =>
        new ErrorContext(this, exception);

        protected override IProcedureEventContext ToProcedureEventContext(ProcedureEvent procedureEvent) =>
        new ProcedureEventContext(this, procedureEvent);

        protected override bool Dispatch(IReducerEventContext context, Reducer reducer)
        {
            var eventContext = (ReducerEventContext)context;
            return reducer switch
            {
                Reducer.CancelDelete args => Reducers.InvokeCancelDelete(eventContext, args),
                Reducer.ChangePassword args => Reducers.InvokeChangePassword(eventContext, args),
                Reducer.ClearBattleConf args => Reducers.InvokeClearBattleConf(eventContext, args),
                Reducer.ConfirmDelete args => Reducers.InvokeConfirmDelete(eventContext, args),
                Reducer.CreateCharacter args => Reducers.InvokeCreateCharacter(eventContext, args),
                Reducer.CutoverAbort args => Reducers.InvokeCutoverAbort(eventContext, args),
                Reducer.CutoverBegin args => Reducers.InvokeCutoverBegin(eventContext, args),
                Reducer.CutoverChunk args => Reducers.InvokeCutoverChunk(eventContext, args),
                Reducer.CutoverCommit args => Reducers.InvokeCutoverCommit(eventContext, args),
                Reducer.CutoverFreeze args => Reducers.InvokeCutoverFreeze(eventContext, args),
                Reducer.Hello args => Reducers.InvokeHello(eventContext, args),
                Reducer.Horde args => Reducers.InvokeHorde(eventContext, args),
                Reducer.HordeSettings args => Reducers.InvokeHordeSettings(eventContext, args),
                Reducer.HordeTestHold args => Reducers.InvokeHordeTestHold(eventContext, args),
                Reducer.Login args => Reducers.InvokeLogin(eventContext, args),
                Reducer.Logout args => Reducers.InvokeLogout(eventContext, args),
                Reducer.MapDisconnect args => Reducers.InvokeMapDisconnect(eventContext, args),
                Reducer.MoveCharacterSlot args => Reducers.InvokeMoveCharacterSlot(eventContext, args),
                Reducer.OwnerResetPassword args => Reducers.InvokeOwnerResetPassword(eventContext, args),
                Reducer.Packet args => Reducers.InvokePacket(eventContext, args),
                Reducer.Presence args => Reducers.InvokePresence(eventContext, args),
                Reducer.Register args => Reducers.InvokeRegister(eventContext, args),
                Reducer.RenameCharacter args => Reducers.InvokeRenameCharacter(eventContext, args),
                Reducer.RenameCheck args => Reducers.InvokeRenameCheck(eventContext, args),
                Reducer.RequestDelete args => Reducers.InvokeRequestDelete(eventContext, args),
                Reducer.SelectCharacter args => Reducers.InvokeSelectCharacter(eventContext, args),
                Reducer.SetBattleConf args => Reducers.InvokeSetBattleConf(eventContext, args),
                Reducer.SetBattleFlag args => Reducers.InvokeSetBattleFlag(eventContext, args),
                Reducer.SetServerMode args => Reducers.InvokeSetServerMode(eventContext, args),
                _ => throw new ArgumentOutOfRangeException("Reducer", $"Unknown reducer {reducer}")
            };
        }

        public SubscriptionBuilder SubscriptionBuilder() => new(this);
        public event Action<ReducerEventContext, Exception> OnUnhandledReducerError
        {
            add => Reducers.InternalOnUnhandledReducerError += value;
            remove => Reducers.InternalOnUnhandledReducerError -= value;
